package com.queryx.database.entities;
import jakarta.persistence.*; import java.io.Serializable; import java.util.UUID;
@Entity @Table(name="investigation_events") @IdClass(InvestigationEvent.Key.class) public class InvestigationEvent { @Id @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="investigation_id") private Investigation investigation; @Id @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="regional_event_id") private RegionalEvent regionalEvent; public Investigation getInvestigation(){return investigation;} public void setInvestigation(Investigation v){investigation=v;} public RegionalEvent getRegionalEvent(){return regionalEvent;} public void setRegionalEvent(RegionalEvent v){regionalEvent=v;} public static class Key implements Serializable { public UUID investigation; public UUID regionalEvent; public boolean equals(Object o){return o instanceof Key k && java.util.Objects.equals(investigation,k.investigation)&&java.util.Objects.equals(regionalEvent,k.regionalEvent);} public int hashCode(){return java.util.Objects.hash(investigation,regionalEvent);} } }
